            "field name": "Transcript implicated by Hi-C",
            "raw field": "hic_transcript_id"
        },
        {
            "type": "join",
            "field name": "Chromosome:coordinate of one loop end",
            "fields to join": ["hic_chr1", "hic_fragmentMid1"],
            "join by": ":"
        },
        {
            "type": "join",
            "field name": "Chromosome:coordinate of other loop end",
            "fields to join": ["hic_chr2", "hic_fragmentMid2"],
            "join by": ":"
        },
        {
            "type": "raw",
            "field name": "Hi-C contact count",
            "raw field": "hic_contactCount"
        },
        {
            "type": "raw",
            "field name": "Hi-C p-value",
            "raw field": "hic_p.value"
        },
