        "PP H0",
        "PP H1",
        "PP H2",
        "PP H3",
        "PP H4",
        "Implicated gene",
        "Implicated gene ID",
        "Implicated gene biotype",
        "Implicated gene type",
        "Cell or tissue type",
        "Gene in GWAS locus",
        "GWAS signal rsID",
        "Signal type"
    ],
    "tool tips": {
        "No. SNPs": "Number of SNPs considered in colocalization analysis",
        "PP H0": "Posterior probability of no signal",
        "PP H1": "Posterior probability of eQTL signal only",
        "PP H2": "Posterior probability of GWAS signal only",
        "PP H3": "Posterior probability of both eQTL and GWAS signals, not colocalized",
        "PP H4": "Posterior probability of colocalized eQTL and GWAS signals. An accepted threshold for significance is 0.8.",
        "Implicated gene": "The gene implicated by colocalization of eQTL and GWAS signals and/or chromatin loops",
        "Cell or tissue type": "The cell or tissue type used in the eQTL analysis",
        "Gene in GWAS locus": "The closest gene to the GWAS signal",
        "GWAS signal rsID": "The GWAS index SNP",
        "Signal type": "P = primary; S = secondary",
        "GWAS beta": "Effect size of the GWAS association",
        "GWAS p-value": "p-value of the GWAS association",
        "GWAS effect allele": "Effect allele of the GWAS association",
        "GWAS other allele": "Other allele of the GWAS association",
        "eQTL SNP": "Variant ID for the eQTL SNP",
        "eQTL nominal p-value": "Nominal p-value of the eQTL",
        "eQTL beta": "Effect size of the eQTL",
        "eQTL SNP other allele": "Other allele of the eQTL SNP",
        "eQTL SNP effect allele": "Effect allele of the eQTL SNP",
        "GWAS genome build": "Genome build of the GWAS",
        "eQTL genome build": "Genome build of the eQTL study",
        "Effect of GWAS signal on target gene expression": "How the GWAS signal affects expression of the target gene",
        "Transcript implicated by Hi-C": "Ensembl ID of the transcript linked to the GWAS signal by Hi-C",
        "Chromosome:coordinate of one loop end": "Coordinate (hg19) of the midpoint for the 2 interacting regions",
        "Chromosome:coordinate of other loop end": "Coordinate (hg19) of the midpoint for the 2 interacting regions",
        "Hi-C contact count": "Number of reads supporting the Hi-C contact",
        "Hi-C p-value": "p-value associated with confidence of the Hi-C contact",
        "Hi-C q-value": "FDR-adjusted Hi-C p-value. An accepted threshold is 1e-6.",
        "Hi-C variant side": "The side of the Hi-C contact on which the variant is located",
        "Hi-C promoter side": "The side of the Hi-C contact on which the gene promoter is located",
        "Hi-C cell or tissue type": "The cell or tissue type used in the Hi-C analysis",
        "Hi-C resolution": "Size (nucleotides) of the window in which the interaction was called",
        "Implicated gene ID": "Ensembl gene ID of the implicated gene",
        "Implicated gene biotype": "Ensembl gene biotype of the implicated gene",
        "Implicated gene type": "Ensembl gene type of the implicated gene"
    },
    "column formatting": {
        "GWAS signal rsID": {
            "type": ["link"],
            "link to": "/variant.html?variant=",
            "new tab": "true"
        },
        "Transcript implicated by Hi-C": {
            "type": ["link"],
            "link to": "https://useast.ensembl.org/Homo_sapiens/Transcript/Summary?t=",
            "new tab": "true"
        },
        "Implicated gene ID": {
            "type": ["link"],
            "link to": "https://useast.ensembl.org/Homo_sapiens/Gene/Summary?g=",
            "new tab": "true"
        }
    },
    "features": [
        "GWAS", 
        "QTLs", 
        "Hi-C"
    ],
    "GWAS": [
        "GWAS other allele",
        "GWAS effect allele",
        "GWAS p-value",
        "GWAS beta",
        "Effect of GWAS signal on target gene expression",
        "GWAS genome build"
    ],
    "QTLs": [
        "eQTL SNP",
        "eQTL SNP other allele",
        "eQTL SNP effect allele",
        "eQTL nominal p-value",
        "eQTL beta",
        "eQTL genome build"
    ],
    "Hi-C": [
        "Transcript implicated by Hi-C",
        "Chromosome:coordinate of one loop end",
        "Chromosome:coordinate of other loop end",
        "Hi-C contact count",
        "Hi-C p-value",
        "Hi-C q-value",
        "Hi-C variant side",
        "Hi-C promoter side",
        "Hi-C cell or tissue type",
        "Hi-C resolution"
    ]
}

